#include "source_spatial_point_ray_adapter_candidate.h"
#include <fstream>
#include <iostream>
template<class T>static void get(std::istream&i,T&v){if(!i.read(reinterpret_cast<char*>(&v),sizeof(v)))throw std::runtime_error("fixture truncated");}
template<class T>static void put(std::ostream&o,const T&v){o.write(reinterpret_cast<const char*>(&v),sizeof(v));}
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"owned x64");if(argc!=3&&argc!=4)throw std::runtime_error("fixture output [explicit-swept] required");const bool explicitSwept=argc==4;if(explicitSwept&&std::string(argv[3])!="explicit-swept")throw std::runtime_error("unknown fixture mode");std::ifstream in(argv[1],std::ios::binary);std::ofstream out(argv[2],std::ios::binary),stored(std::string(argv[2])+".stored-boxes",std::ios::binary);if(!in||!out||!stored)throw std::runtime_error("fixture streams");uint32_t n=0;get(in,n);if(n>4096)throw std::runtime_error("fixture count");std::vector<SourceSpatialPointEntryCandidate>entries(n);for(auto&e:entries){get(in,e.entityId);get(in,e.mask);get(in,e.bounds);}const SourceSpatialPointPartitionCandidate partition(entries);put(out,n);for(uint32_t i=0;i<n;++i){put(out,uint16_t(i));put(stored,partition.storedBounds(i));put(stored,partition.storedMask(i));put(stored,partition.storedFlags(i));}uint32_t queries;get(in,queries);put(out,queries);for(uint32_t i=0;i<queries;++i){uint32_t mask,coarse,stop;std::array<float,6>q;get(in,mask);get(in,q);get(in,coarse);get(in,stop);if(coarse)throw std::runtime_error("coarse point query unsupported");std::vector<uint64_t>answer;if(explicitSwept){uint32_t swept=0;get(in,swept);if(swept>1)throw std::runtime_error("invalid explicit swept flag");const SourceWorldLightRayCandidate ray{{q[0],q[1],q[2]},{q[3],q[4],q[5]},swept!=0};answer=sourceSpatialPointEnumerateRayCandidate(partition,ray,mask,stop);}else answer=partition.queryPoint({q[0],q[1],q[2]},{q[3],q[4],q[5]},mask,stop);put(out,uint32_t(answer.size()));for(uint64_t id:answer)put(out,id);}out.flush();stored.flush();if(!out||!stored)throw std::runtime_error("output failed");std::cout<<"PASS owned x64 point partition entities="<<n<<" queries="<<queries<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
